import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易尚氏學簡介","description":"周易尚氏學 - 周易尚氏學簡介","frontmatter":{"title":"周易尚氏學簡介","description":"周易尚氏學 - 周易尚氏學簡介"},"headers":[],"relativePath":"classics/shangshi/001.md","filePath":"classics/shangshi/001.md"}'),r={name:"classics/shangshi/001.md"};function i(c,a,o,p,d,h){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易尚氏學簡介",tabindex:"-1"},[n("周易尚氏學簡介 "),e("a",{class:"header-anchor",href:"#周易尚氏學簡介","aria-label":"Permalink to “周易尚氏學簡介”"},"​")],-1),e("p",null,"注意",-1),e("p",null,"本站為掃描版，錯字較多，請對比著看！！",-1),e("p",null,"《周易尚氏學》是由尚秉和先生所著，對《周易》進行深入研究和註釋的學術著作。尚秉和，字節之，號滋溪老人、石煙道人，是河北行唐人，晚清進士，易學家。他博學多才，不僅精通易學，還擅長文學、中醫、金石和繪畫。尚秉和先生在易學領域造詣深厚，著述豐富，其中《周易尚氏學》和《周易古筮考》是他的代表作。",-1),e("p",null,"在《周易尚氏學》中，尚秉和先生繼承了象數學的傳統，認為《易經》的卦爻辭都是從卦象中派生出來的，因此他在書中重點通過卦象來解釋《易經》。他強調，要理解《易經》，必須先了解卦爻辭是如何從卦象中產生的，這樣卦象和卦辭才能相互關聯。",-1),e("p",null,"該書對《易經》的卦象進行了歸納整理和推洐，提出了完整而詳備的卦象說。同時，尚秉和先生廣泛蒐集了古人的筮案，並從學術角度進行了詳細的考釋。他還對《易經》中的象數進行了闡發，對筮法進行了研究，提出瞭解《易》的新思路。",-1),e("p",null,"《周易尚氏學》共有二十卷，內容涵蓋了《周易》的上經、下經以及繫辭上傳、下傳等部分，還包括了附錄，如《周易古筮考》、《左傳》《國語》易象釋等，為易學愛好者和研究者提供了重要的文獻參考價值。",-1),e("p",null,"尚秉和先生的這部作品，不僅在易學界產生了深遠的影響，也為後來的學者提供了寶貴的研究資料和新的研究視角。通過他的努力，易學的研究得以進一步深化和發展。",-1)])])}const _=s(r,[["render",i]]);export{m as __pageData,_ as default};
